    sell_book = []  # list of [price, arrival_time, id, qty]
    order_map = {}  # id -> [side, price, arrival_time, qty]
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, arr_time, qty = order_map[order_id]
                del order_map[order_id]
                # Remove from book
                if side == 'buy':
                    buy_book[:] = [o for o in buy_book if o[2] != order_id]
